-- Fork migration 124: the rules of a module of the database, set by an admin: which columns its list has (the built-in ones and any of its
-- fields, in order, with a label), which field holds the sequence (for the length and GC of a list of primers) and whether a sequence file
-- is needed to register an entry in the lab Database. The seven modules the database started with get the columns they had
ALTER TABLE `inventory_categories` ADD COLUMN `settings` JSON NULL DEFAULT NULL;
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Backbone","label":"Backbone"},{"key":"field:Resistance","label":"Selection"},{"key":"files","label":"Sequence"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":null,"requires_sequence_file":true}' WHERE `title` = 'Plasmids';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Sequence","label":"Sequence 5''-3''"},{"key":"calc:length","label":"Length"},{"key":"field:Tm","label":"Tm (°C)"},{"key":"calc:gc","label":"GC %"},{"key":"field:Orientation","label":"Orientation"},{"key":"field:Target","label":"Target"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":"Sequence","requires_sequence_file":false}' WHERE `title` = 'Primers';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Sequence","label":"Sequence 5''-3''"},{"key":"calc:length","label":"Length"},{"key":"calc:gc","label":"GC %"},{"key":"field:Target","label":"Target"},{"key":"field:Label","label":"Label"},{"key":"field:Type","label":"Type"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":"Sequence","requires_sequence_file":false}' WHERE `title` = 'Probes';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Target","label":"Target"},{"key":"field:Host species","label":"Host"},{"key":"field:Antibody type","label":"Primary / secondary"},{"key":"field:Conjugate","label":"Dye"},{"key":"field:Dilution","label":"Dilution"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":null,"requires_sequence_file":false}' WHERE `title` = 'Antibodies';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Kind","label":"Kind"},{"key":"field:Species","label":"Species / organism"},{"key":"field:Genotype","label":"Genotype / tissue"},{"key":"field:Resistance","label":"Selection"},{"key":"field:Mycoplasma","label":"Mycoplasma"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":null,"requires_sequence_file":false}' WHERE `title` = 'Cells & strains';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Reagent type","label":"Type"},{"key":"field:Supplier","label":"Supplier"},{"key":"field:Catalog","label":"Catalog no."},{"key":"field:Lot","label":"Lot"},{"key":"field:Expiry","label":"Expiry"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":null,"requires_sequence_file":false}' WHERE `title` = 'Reagents';
UPDATE `inventory_categories` SET `settings` = '{"columns":[{"key":"field:Sample type","label":"Sample type"},{"key":"field:Date collected","label":"Date collected"},{"key":"quantity","label":"Quantity"},{"key":"owner","label":"Owner"}],"sequence_field":null,"requires_sequence_file":false}' WHERE `title` = 'Samples';
